-- Just transition Topic (Q47) and its sub-topics. Generated by build_topic_sql.py; do not edit.
-- WHAT YOU GET: rows with a `section` (year / corpus / ndc3 / region); see the script docstring.
-- Unit: passages (paragraphs and list items, >= 20 characters) in published documents with
-- classifier output. UNFCCC submissions by Parties only, without inventories. Laws and policies tagged
-- only with the Nature domain are left out. Co-occurrence columns count Q47 passages only.
with unfccc as (  -- UNFCCC submissions by Parties (incl. negotiating groups): the principal
                  -- carries author_type 'Party'; documents inherit it through principal_id
  select distinct d.id
  from PRODUCTION.PUBLISHED.DOCUMENTS d
  join PRODUCTION.PUBLISHED.DOCUMENTS pr on pr.id = d.principal_id,
       lateral flatten(input => d.labels) l, lateral flatten(input => pr.labels) a
  where d.category = 'UN submission' and l.value:id::string = 'un_convention::UNFCCC'
    and a.value:id::string = 'author_type::Party'
),
docs as (
  select d.id, year(d.published_date) as yr,
         case d.category when 'UN submission' then 'UNFCCC submissions'
                         when 'Policy' then 'Policies'
                         when 'Law' then 'Laws'
                         when 'Multilateral Climate Fund project' then 'Climate fund projects'
                         when 'Litigation' then 'Court documents' end as corpus,
         iff(d.entity_type = 'Nationally Determined Contribution (NDC)' and year(d.published_date) >= 2025, 1, 0) as ndc3,
         iff(array_size(d.regions) = 1 and d.category in ('Law', 'Policy', 'UN submission'),
             replace(d.regions[0]::string, 'East Asia and Pacific', 'East Asia & Pacific'), null) as region
  from PRODUCTION.PUBLISHED.DOCUMENTS d
  where not d.is_principal and not d.is_collection and d.document_status = 'published'
    and d.concept_ids is not null
    and d.category in ('UN submission', 'Policy', 'Law', 'Multilateral Climate Fund project', 'Litigation')
    and (d.category not in ('Law', 'Policy') or array_contains('Climate'::variant, d.domains))
    and (d.category <> 'UN submission'
         or (d.id in (select id from unfccc)
             and coalesce(d.entity_type, '') <> 'National Inventory Report (NIR)'
             and not (d.title ilike '%inventory%' or d.title ilike '%common reporting table%' or d.title like '%CRT%')))
),
ndc_country as (
  select d.id, replace(g.value::string, 'country::', '') as iso
  from PRODUCTION.PUBLISHED.DOCUMENTS d, lateral flatten(input => d.geographies) g
  where d.entity_type = 'Nationally Determined Contribution (NDC)' and year(d.published_date) >= 2025
    and g.value::string like 'country::%'
),
f as (
  select dc.id as doc_id, dc.yr, dc.corpus, dc.ndc3, dc.region,
         iff(array_contains('Q47'::variant, p.concept_ids), 1, 0) as jt,
         iff(array_contains('Q53'::variant, p.concept_ids), 1, 0) as socprot,
         iff(array_contains('Q58'::variant, p.concept_ids), 1, 0) as inclusion,
         iff(array_contains('Q1744'::variant, p.concept_ids), 1, 0) as legal,
         iff(array_contains('Q68'::variant, p.concept_ids), 1, 0) as decent,
         iff(array_contains('Q1754'::variant, p.concept_ids), 1, 0) as skills,
         iff(array_contains('Q69'::variant, p.concept_ids), 1, 0) as greenjobs,
         iff(array_contains('Q638'::variant, p.concept_ids), 1, 0) as fossil,
         iff(array_contains('Q661'::variant, p.concept_ids), 1, 0) as coal,
         iff(array_contains('Q2420'::variant, p.concept_ids), 1, 0) as supplymit,
         iff(array_contains('Q567'::variant, p.concept_ids), 1, 0) as renew,
         iff(array_contains('Q2419'::variant, p.concept_ids), 1, 0) as electrif,
         iff(array_contains('Q2421'::variant, p.concept_ids), 1, 0) as grid,
         iff(array_contains('Q287'::variant, p.concept_ids), 1, 0) as storage,
         iff(array_contains('Q762'::variant, p.concept_ids), 1, 0) as esector,
         iff(array_contains('Q757'::variant, p.concept_ids), 1, 0) as informal,
         case when array_contains('Q47'::variant, p.concept_ids) and (regexp_instr(p.content, '\\b((dialogue[[:space:]\\-–—]+(round[[:space:]\\-–—]+(tables?|tables(es)?)|roundtables?|roundtables(es)?)|inclusive[[:space:]\\-–—]+(dialogues?|round[[:space:]\\-–—]+(tables?|tables(es)?)|roundtables?|roundtables(es)?|spaces?)|industrial[[:space:]\\-–—]+councils?|labor[[:space:]\\-–—]+(councils?|unions(es)?)|labour[[:space:]\\-–—]+(unions?|unions(es)?)|multi[[:space:]\\-–—]+(actor[[:space:]\\-–—]+(dialogues?|exchanges?)|sector[[:space:]\\-–—]+dialogues?|sectoral[[:space:]\\-–—]+dialogues?)|social[[:space:]\\-–—]+(dialogues?|exchanges?|partners?|partners(es)?)|stakeholder[[:space:]\\-–—]+dialogues?|trade[[:space:]\\-–—]+(unions?|unions(es)?)|trades[[:space:]\\-–—]+councils?|workers[[:space:]\\-–—]+(collectives?|collectives(es)?)))\\b', 1, 1, 0, 'i') > 0) then 1 else 0 end as dialogue,
         case when array_contains('Q47'::variant, p.concept_ids) and (regexp_instr(p.content, '\\b((addressing[[:space:]\\-–—]+job[[:space:]\\-–—]+(displacements?|loss(es)?)|affected[[:space:]\\-–—]+by[[:space:]\\-–—]+the[[:space:]\\-–—]+(green[[:space:]\\-–—]+transitions?|transitions?)|alleviate[[:space:]\\-–—]+(any[[:space:]\\-–—]+job[[:space:]\\-–—]+losses(es)?|job[[:space:]\\-–—]+(displacements?|loss(es)?|losses(es)?)|loss[[:space:]\\-–—]+off[[:space:]\\-–—]+employments?)|alleviates[[:space:]\\-–—]+(any[[:space:]\\-–—]+job[[:space:]\\-–—]+losses(es)?|job[[:space:]\\-–—]+(displacements?|loss(es)?|losses(es)?)|loss[[:space:]\\-–—]+off[[:space:]\\-–—]+employments?)|alternatives[[:space:]\\-–—]+for[[:space:]\\-–—]+fossil[[:space:]\\-–—]+fuel[[:space:]\\-–—]+workers(es)?|assistance[[:space:]\\-–—]+for[[:space:]\\-–—]+workers[[:space:]\\-–—]+impacted[[:space:]\\-–—]+by[[:space:]\\-–—]+the[[:space:]\\-–—]+energy[[:space:]\\-–—]+transitions?|assisting[[:space:]\\-–—]+(communities[[:space:]\\-–—]+impacted[[:space:]\\-–—]+by[[:space:]\\-–—]+this[[:space:]\\-–—]+transitions?|laborers[[:space:]\\-–—]+affected[[:space:]\\-–—]+most[[:space:]\\-–—]+by[[:space:]\\-–—]+the[[:space:]\\-–—]+transformations(es)?)|collaborates[[:space:]\\-–—]+with[[:space:]\\-–—]+labourers[[:space:]\\-–—]+impacted[[:space:]\\-–—]+most[[:space:]\\-–—]+by[[:space:]\\-–—]+the[[:space:]\\-–—]+transitions?|decrease[[:space:]\\-–—]+(any[[:space:]\\-–—]+job[[:space:]\\-–—]+losses(es)?|job[[:space:]\\-–—]+(displacements?|loss(es)?|losses(es)?)|loss[[:space:]\\-–—]+off[[:space:]\\-–—]+employments?)|decreases[[:space:]\\-–—]+(any[[:space:]\\-–—]+job[[:space:]\\-–—]+losses(es)?|job[[:space:]\\-–—]+(displacements?|loss(es)?|losses(es)?)|loss[[:space:]\\-–—]+off[[:space:]\\-–—]+employments?)|decreasing[[:space:]\\-–—]+(any[[:space:]\\-–—]+job[[:space:]\\-–—]+losses(es)?|job[[:space:]\\-–—]+(displacements?|loss(es)?|losses(es)?)|loss[[:space:]\\-–—]+off[[:space:]\\-–—]+employments?)|developed[[:space:]\\-–—]+with