         iff(array_contains('Q47'::variant, p.concept_ids) and not (array_contains('Q68'::variant, p.concept_ids) or array_contains('Q1754'::variant, p.concept_ids) or array_contains('Q69'::variant, p.concept_ids)) and not (array_contains('Q53'::variant, p.concept_ids) or array_contains('Q58'::variant, p.concept_ids) or array_contains('Q1744'::variant, p.concept_ids)), 1, 0) as g_generic,
         iff(array_contains('Q68'::variant, p.concept_ids) or array_contains('Q1754'::variant, p.concept_ids) or array_contains('Q69'::variant, p.concept_ids), 1, 0) as any_work,
         iff((iff(array_contains('Q68'::variant, p.concept_ids) or array_contains('Q1754'::variant, p.concept_ids) or array_contains('Q69'::variant, p.concept_ids), 1, 0) + iff(array_contains('Q53'::variant, p.concept_ids), 1, 0) + iff(array_contains('Q58'::variant, p.concept_ids) or array_contains('Q1744'::variant, p.concept_ids), 1, 0)) = 1 and iff(array_contains('Q68'::variant, p.concept_ids) or array_contains('Q1754'::variant, p.concept_ids) or array_contains('Q69'::variant, p.concept_ids), 1, 0) = 1, 1, 0) as c_work,
         iff((iff(array_contains('Q68'::variant, p.concept_ids) or array_contains('Q1754'::variant, p.concept_ids) or array_contains('Q69'::variant, p.concept_ids), 1, 0) + iff(array_contains('Q53'::variant, p.concept_ids), 1, 0) + iff(array_contains('Q58'::variant, p.concept_ids) or array_contains('Q1744'::variant, p.concept_ids), 1, 0)) = 1 and iff(array_contains('Q53'::variant, p.concept_ids), 1, 0) = 1, 1, 0) as c_protect,
