select 'year' as section, corpus as grp, yr, count(*) as passages, sum(jt) as jt, sum(iff(jt = 1, socprot, 0)) as socprot, sum(iff(jt = 1, inclusion, 0)) as inclusion, sum(iff(jt = 1, legal, 0)) as legal, sum(iff(jt = 1, decent, 0)) as decent, sum(iff(jt = 1, skills, 0)) as skills, sum(iff(jt = 1, greenjobs, 0)) as greenjobs, sum(iff(jt = 1, fossil, 0)) as fossil, sum(iff(jt = 1, coal, 0)) as coal, sum(iff(jt = 1, supplymit, 0)) as supplymit, sum(iff(jt = 1, renew, 0)) as renew, sum(iff(jt = 1, electrif, 0)) as electrif, sum(iff(jt = 1, grid, 0)) as grid, sum(iff(jt = 1, storage, 0)) as storage, sum(iff(jt = 1, esector, 0)) as esector, sum(iff(jt = 1, informal, 0)) as informal, sum(iff(jt = 1, dialogue, 0)) as dialogue, sum(iff(jt = 1, transition_workers, 0)) as transition_workers, sum(iff(jt = 1, g_work, 0)) as g_work, sum(iff(jt = 1, g_protect, 0)) as g_protect, sum(iff(jt = 1, g_both, 0)) as g_both, sum(iff(jt = 1, g_generic, 0)) as g_generic, sum(iff(jt = 1, any_energy, 0)) as any_energy, sum(iff(jt = 1, any_work, 0)) as any_work, sum(iff(jt = 1, c_work, 0)) as c_work, sum(iff(jt = 1, c_protect, 0)) as c_protect, sum(iff(jt = 1, c_include, 0)) as c_include, sum(iff(jt = 1, c_multiple, 0)) as c_multiple
from f where yr between 2012 and 2025 group by corpus, yr
union all
select 'corpus', coalesce(corpus, 'All'), null, count(*), sum(jt) as jt, sum(iff(jt = 1, socprot, 0)) as socprot, sum(iff(jt = 1, inclusion, 0)) as inclusion, sum(iff(jt = 1, legal, 0)) as legal, sum(iff(jt = 1, decent, 0)) as decent, sum(iff(jt = 1, skills, 0)) as skills, sum(iff(jt = 1, greenjobs, 0)) as greenjobs, sum(iff(jt = 1, fossil, 0)) as fossil, sum(iff(jt = 1, coal, 0)) as coal, sum(iff(jt = 1, supplymit, 0)) as supplymit, sum(iff(jt = 1, renew, 0)) as renew, sum(iff(jt = 1, electrif, 0)) as electrif, sum(iff(jt = 1, grid, 0)) as grid, sum(iff(jt = 1, storage, 0)) as storage, sum(iff(jt = 1, esector, 0)) as esector, sum(iff(jt = 1, informal, 0)) as informal, sum(iff(jt = 1, dialogue, 0)) as dialogue, sum(iff(jt = 1, transition_workers, 0)) as transition_workers, sum(iff(jt = 1, g_work, 0)) as g_work, sum(iff(jt = 1, g_protect, 0)) as g_protect, sum(iff(jt = 1, g_both, 0)) as g_both, sum(iff(jt = 1, g_generic, 0)) as g_generic, sum(iff(jt = 1, any_energy, 0)) as any_energy, sum(iff(jt = 1, any_work, 0)) as any_work, sum(iff(jt = 1, c_work, 0)) as c_work, sum(iff(jt = 1, c_protect, 0)) as c_protect, sum(iff(jt = 1, c_include, 0)) as c_include, sum(iff(jt = 1, c_multiple, 0)) as c_multiple
from f where yr between 2020 and 2025 group by grouping sets ((corpus), ())
union all
select 'ndc3', n.iso, null, count(*), max(jt) as jt, max(socprot) as socprot, max(inclusion) as inclusion, max(legal) as legal, max(decent) as decent, max(skills) as skills, max(greenjobs) as greenjobs, max(fossil) as fossil, max(coal) as coal, max(supplymit) as supplymit, max(renew) as renew, max(electrif) as electrif, max(grid) as grid, max(storage) as storage, max(esector) as esector, max(informal) as informal, max(dialogue) as dialogue, max(transition_workers) as transition_workers, max(g_work) as g_work, max(g_protect) as g_protect, max(g_both) as g_both, max(g_generic) as g_generic, max(any_energy) as any_energy, max(any_work) as any_work, max(c_work) as c_work, max(c_protect) as c_protect, max(c_include) as c_include, max(c_multiple) as c_multiple
from f join ndc_country n on n.id = f.doc_id where f.ndc3 = 1 group by n.iso
union all
select 'region', region || ' / ' || corpus, null, count(*), sum(jt) as jt, sum(iff(jt = 1, socprot, 0)) as socprot, sum(iff(jt = 1, inclusion, 0)) as inclusion, sum(iff(jt = 1, legal, 0)) as legal, sum(iff(jt = 1, decent, 0)) as decent, sum(iff(jt = 1, skills, 0)) as skills, sum(iff(jt = 1, greenjobs, 0)) as greenjobs, sum(iff(jt = 1, fossil, 0)) as fossil, sum(iff(jt = 1, coal, 0)) as coal, sum(iff(jt = 1, supplymit, 0)) as supplymit, sum(iff(jt = 1, renew, 0)) as renew, sum(iff(jt = 1, electrif, 0)) as electrif, sum(iff(jt = 1, grid, 0)) as grid, sum(iff(jt = 1, storage, 0)) as storage, sum(iff(jt = 1, esector, 0)) as esector, sum(iff(jt = 1, informal, 0)) as informal, sum(iff(jt = 1, dialogue, 0)) as dialogue, sum(iff(jt = 1, transition_workers, 0)) as transition_workers, sum(iff(jt = 1, g_work, 0)) as g_work, sum(iff(jt = 1, g_protect, 0)) as g_protect, sum(iff(jt = 1, g_both, 0)) as g_both, sum(iff(jt = 1, g_generic, 0)) as g_generic, sum(iff(jt = 1, any_energy, 0)) as any_energy, sum(iff(jt = 1, any_work, 0)) as any_work, sum(iff(jt = 1, c_work, 0)) as c_work, sum(iff(jt = 1, c_protect, 0)) as c_protect, sum(iff(jt = 1, c_include, 0)) as c_include, sum(iff(jt = 1, c_multiple, 0)) as c_multiple
from f where region is not null and yr between 2020 and 2025 group by region, corpus
